        [$agentB,$versionB]=$this->aggregate([], 'IA09-B');$scenarioB=new SimulationScenario;$scenarioB->agent_id=$agentB->id;$scenarioB->name='B';$scenarioB->enabled=true;$scenarioB->definition=['turns'=>['B'],'action_results'=>[],'simulate_confirmation'=>false,'assertions'=>[['type'=>'response_completed']]];$scenarioB->save();
        foreach([fn()=>app(RunAgentSimulationService::class)->runAll($this->user,$this->agent,$versionB),fn()=>app(RunAgentSimulationService::class)->runAll($this->user,$this->agent,$this->version,$scenarioB),fn()=>app(PublishReadyAgentVersionService::class)->publish($this->user,$this->agent,$versionB)]as$operation){try{$operation();$this->fail('Same-tenant aggregate mismatch must fail.');}catch(\Throwable){$this->addToAssertionCount(1);}}
        $this->gateway->responses=[$this->answerResponse('B')];$runB=app(RunAgentSimulationService::class)->runAll($this->user,$agentB,$versionB,$scenarioB);$scenarioA=$this->scenario('A',['turns'=>['A'],'action_results'=>[],'simulate_confirmation'=>false,'assertions'=>[['type'=>'response_completed']]]);$case=new SimulationCaseRun;$case->simulation_run_id=$runB->id;$case->scenario_id=$scenarioA->id;$case->status=SimulationRunStatus::Running;$case->scenario_snapshot=[];$case->transcript=[];$case->observations=[];$case->action_traces=[];try{$case->save();$this->fail('Mismatched CaseRun and Scenario must fail.');}catch(\DomainException){$this->assertTrue(true);}
    }

    public function test_message_fixture_and_transcript_byte_limits_fail_bounded_before_next_model_call():void
    {
        $this->allowActions([]);config(['ai.simulator.max_user_message_bytes'=>100]);$message=$this->scenario('UTF8',['turns'=>['ááá'],'action_results'=>[],'simulate_confirmation'=>false,'assertions'=>[['type'=>'response_completed']]]);config(['ai.simulator.max_user_message_bytes'=>4]);$this->gateway->calls=0;$run=app(RunAgentSimulationService::class)->runAll($this->user,$this->agent,$this->version,$message);$this->assertSame(SimulationRunStatus::Failed,$run->status);$this->assertSame('simulation_message_too_large',$run->cases()->first()->safe_failure_code);$this->assertSame(0,$this->gateway->calls);$this->assertSame([],$run->cases()->first()->transcript);

        config(['ai.simulator.max_user_message_bytes'=>8000,'ai.simulator.max_fixture_bytes'=>1000]);$this->allowActions(['zigo.track_shipment']);$fixture=['shipment_reference'=>str_repeat('S',100),'tracking_reference'=>'T','status_code'=>'IN_TRANSIT','status_label'=>'En tránsito','delivered'=>false,'events'=>[]];$scenario=$this->scenario('Fixture bytes',['turns'=>['Rastrea'],'action_results'=>['zigo.track_shipment'=>$fixture],'simulate_confirmation'=>false,'assertions'=>[['type'=>'response_completed']]]);config(['ai.simulator.max_fixture_bytes'=>50]);$this->gateway->calls=0;$this->gateway->responses=[$this->actionResponse('zigo.track_shipment',['shipment_reference'=>'S'])];$run=app(RunAgentSimulationService::class)->runAll($this->user,$this->agent,$this->version,$scenario);$this->assertSame('simulation_fixture_too_large',$run->cases()->first()->safe_failure_code);$this->assertSame(0,$this->gateway->calls);

        config(['ai.simulator.max_fixture_bytes'=>32768,'ai.simulator.max_transcript_bytes'=>1000]);$this->allowActions([]);$scenario=$this->scenario('Transcript bytes',['turns'=>['Uno','Dos'],'action_results'=>[],'simulate_confirmation'=>false,'assertions'=>[['type'=>'response_completed']]]);config(['ai.simulator.max_transcript_bytes'=>160]);$this->gateway->calls=0;$this->gateway->responses=[$this->answerResponse(str_repeat('A',45)),$this->answerResponse(str_repeat('B',45))];$run=app(RunAgentSimulationService::class)->runAll($this->user,$this->agent,$this->version,$scenario);$case=$run->cases()->first();$this->assertSame('simulation_transcript_too_large',$case->safe_failure_code);$this->assertLessThanOrEqual(160,app(\App\Domain\AI\Simulator\Support\SimulationPayloadLimits::class)->jsonBytes($case->transcript));$this->assertNotContains(str_repeat('B',45),array_column($case->transcript,'content'));$this->assertSame(2,$this->gateway->calls);Http::assertNothingSent();
    }

    public function test_publish_revalidates_current_entitlement_authority_inside_protected_boundary():void
    {
        $this->gateway->responses=[$this->actionResponse('zigo.track_shipment',['shipment_reference'=>'S']),$this->answerResponse('Rastreado')];$this->scenario('Entitlement publish',['turns'=>['Rastrea'],'action_results'=>['zigo.track_shipment'=>['shipment_reference'=>'S','tracking_reference'=>'T','status_code'=>'IN_TRANSIT','status_label'=>'En tránsito','delivered'=>false,'events'=>[]]],'simulate_confirmation'=>false,'assertions'=>[['type'=>'response_completed']]]);app(RunAgentSimulationService::class)->runAll($this->user,$this->agent,$this->version);$this->prepareApproved($this->version);$this->assertTrue(app(AiReadinessService::class)->evaluate($this->agent,$this->version)->ready);DB::table('network_entitlements')->where('tenant_id',$this->tenant->id)->where('code','TRACKING')->update(['is_enabled'=>false]);try{app(PublishReadyAgentVersionService::class)->publish($this->user,$this->agent,$this->version);$this->fail('Current entitlement revocation must block publish.');}catch(\DomainException){$this->assertNull($this->agent->fresh()->current_published_version_id);}
    }

    private function scenario(string$name,array$definition):SimulationScenario{$scenario=new SimulationScenario;$scenario->agent_id=$this->agent->id;$scenario->name=$name;$scenario->enabled=true;$scenario->definition=$definition;$scenario->save();return$scenario;}
    private function actionResponse(string$key,array$arguments,array$extra=[]):array{return array_merge($this->base('Solicitando acción'),$extra,['action_request'=>['action_key'=>$key,'arguments'=>$arguments]]);}
    private function answerResponse(string$answer,bool$lead=false,bool$outcome=false,bool$handoff=false):array{$base=$this->base($answer,$handoff);$base['lead_candidate']=$lead?['fields'=>[['key'=>'name','value'=>'Persona']]]:null;$base['resolved_candidate']=$outcome;return$base;}
    private function base(string$answer,bool$handoff=false):array{return['answer'=>$answer,'citation_ids'=>['K1'],'confidence'=>$handoff?'medium':'high','needs_handoff'=>$handoff,'handoff_reason'=>$handoff?'human_requested':'none','lead_candidate'=>null,'resolved_candidate'=>false];}
    private function sideEffects():array{return['actions'=>ActionRun::count(),'leads'=>Lead::count(),'outcomes'=>OutcomeEvent::count(),'handoffs'=>HumanHandoff::count(),'operations'=>TenantOperation::count(),'shipments'=>LocalShipment::count()];}
    private function allowActions(array$keys):void{DB::table('ai_agent_contract_versions')->where('id',$this->version->agent_contract_version_id)->update(['allowed_actions'=>json_encode($keys)]);$this->version->unsetRelation('contractVersion');$this->version->load('contractVersion');}
    private function prepareApproved(AgentVersion$version):void{$hash=app(CanonicalJsonHasher::class)->hash(['schema_version'=>$version->schema_version,'configuration'=>$version->configuration]);DB::table('ai_agent_versions')->where('id',$version->id)->update(['status'=>'approved','configuration_hash'=>$hash,'testing_at'=>now(),'approved_at'=>now(),'approved_by_user_id'=>$this->user->id,'approval_evidence'=>json_encode(['manual_review'=>true])]);$version->refresh();}

    private function aggregate(array$actions,string$code='IA09'):array
    {
        $agentId=DB::table('ai_agents')->insertGetId(['tenant_id'=>$this->tenant->id,'code'=>$code,'name'=>'Agente','type'=>'sales','status'=>'draft','created_by_user_id'=>$this->user->id,'created_at'=>now(),'updated_at'=>now()]);$contractId=DB::table('ai_agent_contracts')->insertGetId(['tenant_id'=>$this->tenant->id,'agent_id'=>$agentId,'status'=>'active','created_by_user_id'=>$this->user->id,'created_at'=>now(),'updated_at'=>now()]);$cvId=DB::table('ai_agent_contract_versions')->insertGetId(['tenant_id'=>$this->tenant->id,'agent_contract_id'=>$contractId,'version_number'=>1,'status'=>'accepted','job_to_be_done'=>'Atender','objectives'=>'[]','allowed_capabilities'=>'[]','prohibited_capabilities'=>'[]','channels'=>'[]','knowledge_requirements'=>'[]','allowed_actions'=>json_encode($actions),'handoff_policy'=>'[]','outcome_policy'=>'[]','capacity_policy'=>'[]','sla_policy'=>'[]','privacy_policy'=>'[]','pricing_policy'=>'[]','created_by_user_id'=>$this->user->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_agent_contracts')->where('id',$contractId)->update(['current_accepted_version_id'=>$cvId]);$versionId=DB::table('ai_agent_versions')->insertGetId(['tenant_id'=>$this->tenant->id,'agent_id'=>$agentId,'agent_contract_version_id'=>$cvId,'version_number'=>1,'status'=>'testing','schema_version'=>'1.0','configuration'=>'{}','created_by_user_id'=>$this->user->id,'created_at'=>now(),'updated_at'=>now()]);return[Agent::findOrFail($agentId),AgentVersion::with('contractVersion')->findOrFail($versionId)];
    }
    private function entitle(string$code):void{$module=DB::table('network_modules')->where('code',$code)->first();if(!$module){$id=DB::table('network_modules')->insertGetId(['code'=>$code,'name'=>$code,'type'=>'core','is_active'=>true,'sort_order'=>1,'created_at'=>now(),'updated_at'=>now()]);}else$id=$module->id;$subscription=DB::table('network_subscriptions')->where('tenant_id',$this->tenant->id)->value('id');if(!$subscription){$plan=DB::table('network_plans')->insertGetId(['code'=>'P'.$this->tenant->id,'name'=>'Plan','status'=>'active','currency'=>'MXN','created_at'=>now(),'updated_at'=>now()]);$subscription=DB::table('network_subscriptions')->insertGetId(['uuid'=>(string)Str::uuid(),'tenant_id'=>$this->tenant->id,'plan_id'=>$plan,'status'=>'active','started_at'=>now()->subDay(),'current_period_start'=>now()->subDay(),'current_period_end'=>now()->addMonth(),'created_at'=>now(),'updated_at'=>now()]);}DB::table('network_entitlements')->insert(['subscription_id'=>$subscription,'tenant_id'=>$this->tenant->id,'module_id'=>$id,'code'=>$code,'is_enabled'=>true,'source'=>'plan','created_at'=>now(),'updated_at'=>now()]);}

    private function schema():void
    {
        Schema::create('users',function(Blueprint$t){$t->id();$t->string('name');$t->string('email')->unique();$t->string('password');$t->unsignedBigInteger('empresa_id');$t->rememberToken();$t->timestamps();});Schema::create('network_tenants',function(Blueprint$t){$t->id();$t->uuid('uuid')->nullable();$t->string('name');$t->string('slug')->unique();$t->string('status');$t->timestamps();});Schema::create('network_tenant_memberships',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('user_id');$t->string('role');$t->string('status');$t->timestamps();});Schema::create('network_plans',function(Blueprint$t){$t->id();$t->string('code');$t->string('name');$t->string('status');$t->string('currency');$t->timestamps();});Schema::create('network_modules',function(Blueprint$t){$t->id();$t->string('code')->unique();$t->string('name');$t->string('type');$t->boolean('is_active');$t->integer('sort_order');$t->timestamps();});Schema::create('network_subscriptions',function(Blueprint$t){$t->id();$t->uuid('uuid');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('plan_id');$t->string('status');foreach(['started_at','current_period_start','current_period_end','trial_ends_at','grace_ends_at','canceled_at','ended_at']as$c)$t->timestamp($c)->nullable();$t->timestamps();});Schema::create('network_entitlements',function(Blueprint$t){$t->id();$t->unsignedBigInteger('subscription_id');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('module_id');$t->string('code');$t->boolean('is_enabled');$t->integer('limit_value')->nullable();$t->string('source');$t->timestamps();});
        (require base_path('database/migrations/2026_08_22_100000_create_ai_agent_domain_tables.php'))->up();(require base_path('database/migrations/2026_08_23_100000_add_ai_agent_lifecycle.php'))->up();(require base_path('database/migrations/2026_08_27_100000_create_ai_runtime_runs.php'))->up();(require base_path('database/migrations/2026_08_27_110000_add_provider_observability_to_ai_runtime_runs.php'))->up();(require base_path('database/migrations/2026_08_30_100000_create_ai_simulator_readiness.php'))->up();
        Schema::create('network_tenant_domains',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->string('domain')->unique();$t->string('type');$t->string('environment');$t->boolean('is_primary');$t->string('status');$t->timestamp('verified_at')->nullable();$t->timestamps();});Schema::create('network_tenant_brandings',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id')->unique();$t->string('brand_name')->nullable();$t->string('primary_color')->nullable();$t->string('secondary_color')->nullable();$t->string('accent_color')->nullable();$t->timestamps();});foreach(['ai_action_runs','ai_leads','ai_outcome_events','ai_human_handoffs','ai_conversations']as$table)Schema::create($table,function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->timestamp('confirmed_at')->nullable();});Schema::create('network_tenant_operations',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->timestamps();});Schema::create('local_shipments',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->json('guide_snapshot')->nullable();$t->timestamps();});
    }
