final class FakeSimulationGateway implements ModelGateway
{
    public array$responses=[];public array$requests=[];public array$transactionLevels=[];public int$calls=0;
    public function generate(ModelRequestData$request):ModelResponseData{$this->calls++;$this->requests[]=$request;$this->transactionLevels[]=DB::transactionLevel();$output=array_shift($this->responses)??throw new \RuntimeException('Missing fake response.');return new ModelResponseData('fake-'.$this->calls,'gpt-5.6-luna','completed',$output,10,0,5,15,1);}
}
final class CountingHandler implements ActionHandler{public int$calls=0;public function execute(ActionExecutionContext$context,array$arguments):ActionResultData{$this->calls++;return new ActionResultData(['value'=>'real']);}}
